import React from "react";
import { useLocation } from "react-router-dom";

function Details() {
  const { state } = useLocation(); // receives item from List

  if (!state) return <p>No employee data found.</p>;

  return (
    <div>
      <h2>{state[0]} - Details</h2>
      <p><strong>Role:</strong> {state[1]}</p>
      <p><strong>Location:</strong> {state[2]}</p>
      <p><strong>ID:</strong> {state[3]}</p>
      <p><strong>Date:</strong> {state[4]}</p>
      <p><strong>Salary:</strong> {state[5]}</p>
    </div>
  );
}

export default Details;
